CREATE OR REPLACE FUNCTION GAF_HTOD(SDURACAO IN VARCHAR2) RETURN NUMBER IS    SDURA   VARCHAR2(8);   NINT    NUMBER;   NDEC    NUMBER;   NRETURN NUMBER; BEGIN   IF INSTR(SDURACAO, '-') > 0 THEN     SDURA := SUBSTR(SDURACAO, 2);   ELSE     SDURA := SDURACAO;   END IF;   NINT := TO_NUMBER(SUBSTR(LPAD(SDURA, 7, '0'), 1, 4));   NDEC := TO_NUMBER(SUBSTR(LPAD(SDURA, 7, '0'), 6, 2)) / 60;   IF INSTR(SDURACAO, '-') > 0 THEN     NRETURN := -1 * (NINT + NDEC);   ELSE     NRETURN := NINT + NDEC;   END IF;   RETURN NRETURN; END;